import { useMutation } from "@tanstack/react-query";

export function usePostServices() {
    return useMutation({
        mutationKey: ["servicesMutation"],
        mutationFn: async (data : { title: string, description: string, content: string, price: string, priceFrom: string, categoryId: string, isOms: string, duration: string, imageUrl: string, isActive: string, doctorIds: string[] }) => {
            const response = await fetch("/api/admin/services", {
                method: "POST",
                headers: { "Content-Type" : "application/json" },
                body: JSON.stringify(data)
            });
            if(!response.ok){
                const error = await response.json();
                throw new Error(error.message || "Ошибка запроса создания сервиса");
            }
            return response.json();
        }
    })
}